export const GAME_MAP = Object.fromEntries(GAMES.map((g) => [g.slug, g]));

export function getGame(slug) {
  return GAME_MAP[slug] ?? null;
}

// Featured carousel
export const FEATURED = GAMES.filter((g) => g.featured);

// Most-played first
export const POPULAR = [...GAMES].sort((a, b) => b.plays - a.plays);

// Newest additions
export const NEW_GAMES = GAMES.filter((g) => g.isNew);

// Games in the same category (excluding the current one)
export function getRelated(slug, limit = 6) {
  const game = GAME_MAP[slug];
  if (!game) return [];
  return GAMES.filter((g) => g.slug !== slug && g.category === game.category).slice(0, limit);
}

// Popular picks that are not the current game (for the sidebar)
export function getRecommended(slug, limit = 6) {
  return POPULAR.filter((g) => g.slug !== slug).slice(0, limit);
}

export function formatPlays(n) {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1).replace(/\.0$/, '') + 'M';
  if (n >= 1_000) return Math.round(n / 1_000) + 'K';
  return String(n);
}
